"""Publish only measured evidence for the 26 November editorial redesign."""
from pathlib import Path
import json,html,shutil
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT.parents[1]/'outputs/hotel-atelier-20261126';DOC=ROOT/'docs'
scores=json.loads((OUT/'lighthouse-results.json').read_text(encoding='utf8')) if (OUT/'lighthouse-results.json').exists() else []
for source,target in [('lighthouse-results.json','atelier-lighthouse-results.json'),('verification.json','atelier-checks.json'),('capture-dimensions.json','atelier-capture-dimensions.json')]:
 if (OUT/source).exists():shutil.copyfile(OUT/source,DOC/target)
rows=''.join('<tr><td>'+r['language'].upper()+'</td><td>'+r['device']+'</td>'+''.join('<td>'+str(r['scores'][key])+'</td>' for key in ['performance','accessibility','best-practices','seo'])+'</tr>' for r in scores)
measurements='<p>Mesures de production en cours de publication ; aucun score n’est présumé.</p>' if not scores else '<p>Dix exécutions Lighthouse séquentielles sur les cinq accueils publiés : mobile et ordinateur. Chromium headless, ralentissement mobile simulé, préréglage ordinateur. Résultats de laboratoire, variables selon les conditions ; aucune donnée terrain revendiquée.</p><div class="table"><table><thead><tr><th>Langue</th><th>Appareil</th><th>Performance</th><th>Accessibilité</th><th>Bonnes pratiques</th><th>SEO</th></tr></thead><tbody>'+rows+'</tbody></table></div><p><a href="atelier-lighthouse-results.json">URL, horodatages, configuration, métriques et empreinte des sources</a>.</p>'
captures=''.join('<li>'+lang.upper()+' : '+', '.join('<a href="captures/'+lang+'/'+name+'.webp">'+label+'</a>' for name,label in [('home','Accueil'),('mobile','Accueil mobile'),('booking','Moteur'),('mobile-booking','Moteur mobile'),('mobile-checkout','Voyageur et paiement d’essai'),('room','Chambre'),('restaurant','Menus'),('table-booking','Table'),('activities','Excursions'),('administration','Administration'),('calendar','Calendrier')])+'</li>' for lang in ['fr','en','it','es','de'])
content='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Casa Suprana — Carnet insulaire, livraison du 26 novembre 2026</title><meta name="robots" content="noindex,follow"><style>body{max-width:1100px;margin:3rem auto;padding:0 1.5rem;font:16px/1.8 system-ui;color:#20221f}h1,h2{line-height:1.15}a{color:inherit}th,td{text-align:left;padding:.7rem;border-bottom:1px solid #ccc}table{width:100%;border-collapse:collapse}.table{overflow:auto}.note{padding:1.5rem;border:1px solid #222;background:#f6f6f1}code{overflow-wrap:anywhere}</style></head><body><h1>Casa Suprana — le carnet insulaire</h1><p>Refonte éditoriale · 26 novembre 2026 · FR / EN / IT / ES / DE</p><p class="note">Un nouveau langage visuel, avec les mêmes moteurs de réservation locaux. Maison fictive, paiements simulés et données conservées dans le navigateur. L’intégration Beds24 de production reste une installation distincte à valider avec des accès autorisés.</p><h2>Direction artistique</h2><p>Un carnet de voyage composé de photographies décalées, de filets doubles, d’un cartouche typographique, de dessins botaniques originaux et d’une rose des vents. Palette blanche, noire et végétale discrète. Les photographies de Saleccia et du littoral corse sont créditées et sous licence Unsplash gratuite ; elles ne représentent pas une plage privée de l’hôtel.</p><p>Référence demandée : <a href="https://www.1-placevendome.com/fr/">1, Place Vendôme</a>. L’inspiration concerne le rythme éditorial et l’esprit de collage ; aucun code, logo, photographie ou texte commercial de ce site n’a été repris. <a href="design-references.md">Étude et provenance</a> · <a href="../assets/images/manifest.json">Crédits photographiques</a>.</p><h2>Mouvement et navigation</h2><p>Branche de maquis, rose des vents et lignes de mer : mouvements brefs, non permanents. Les chapitres apparaissent progressivement dans le défilement natif. Aucune image ne zoome. La préférence <code>prefers-reduced-motion</code> supprime ces effets ; sans JavaScript, le contenu éditorial reste visible. Le menu et le sélecteur de langue ont un fond opaque et restent accessibles au clavier.</p><h2>Fonctions préservées et vérifiées</h2><ul><li>24 tests unitaires réussis sur les règles hôtelières, les tables, les activités et le transport Beds24 simulé.</li><li>120 pages, cinq catalogues complets : aucun lien interne cassé ni erreur de métadonnées au contrôle statique ; les trois fichiers PHP de l’ancien connecteur restent identiques.</li><li>50 contrôles ciblés de mise en page : 35 vues de chambres, restaurant, expériences, moteurs et administration à 320 px ; 15 vues de l’accueil dans les cinq langues, à 320, 768 et 844 px, dont le paysage. Aucun débordement horizontal ni texte sortant du cartouche après correction de la tablette.</li><li>Parcours réellement effectué en français dans l’interface : paiement de séjour refusé puis accepté, modification des voyageurs, annulation, confirmation d’une table et confirmation d’une excursion. Aucun paiement ni message réel.</li><li>Aucune erreur JavaScript détectée dans les vues et captures contrôlées. Les modules métier, les règles et les structures de stockage n’ont pas été remplacés.</li></ul><p>Les audits automatisés ne constituent pas un audit RGAA complet. <a href="atelier-checks.json">Preuves synthétiques de cette refonte</a> · <a href="static-results.json">Contrôle statique</a>.</p><h2>Captures réelles localisées</h2><p>55 captures prises sur les interfaces traduites, puis encodées en WebP. Huit vues ordinateur et trois vues mobile par langue. Fenêtres de contrôle de 1440 × 1000 et 390 × 844 ; les dimensions du contenu capturé varient légèrement selon les barres de défilement du navigateur. Aucun texte n’est remplacé sur les images. Les mêmes fichiers sont publiés dans les fiches du portfolio. <a href="atelier-capture-dimensions.json">Dimensions réellement obtenues</a>.</p><ul>CAPTURES</ul><h2>Lighthouse de cette version publiée</h2>MEASUREMENTS<h2>Architecture et limites</h2><p><a href="../README.md">Architecture et reconstruction</a> · <a href="beds24.html">Connexion Beds24 et limites exactes</a> · <a href="verification.html">Livraison initiale du 25 novembre, tests détaillés et mesures historiques</a> · <a href="file-list.txt">Fichiers du dépôt</a> · <a href="atelier-changed-files.txt">Fichiers de la refonte</a>.</p><p>Cette refonte ne transforme pas la démonstration en PMS de production. Les réservations, tables et excursions restent locales à chaque navigateur ; aucun opérateur réel, paiement, e-mail ou synchronisation distante n’est activé. Les traductions libres ajoutées dans l’administration ne sont pas automatiquement traduites.</p></body></html>'''
(DOC/'atelier-verification.html').write_text(content.replace('CAPTURES',captures).replace('MEASUREMENTS',measurements),encoding='utf8')
print('Generated redesign report with',len(scores),'measured production Lighthouse records.')
